import Fastify from 'fastify';
import {mapSyncError} from './sync-error';
const app=Fastify();
app.post('/api/sync', async (request,reply)=>{const body=request.body as {conflict?:boolean,locked?:boolean}; if(body.conflict) throw Object.assign(new Error('conflict'),{kind:'conflict'}); if(body.locked) throw Object.assign(new Error('locked'),{kind:'locked'}); return {data:{accepted:true}};});
app.setErrorHandler((error,request,reply)=>{const mapped=mapSyncError(error); if(mapped) return reply.code(mapped.status).send(mapped.body); return reply.code(500).send({error:'internal'});});

