export function mapSyncError(error:Error & {kind?:string}){
 if(error.kind==='conflict') return {status:409,body:{code:'SYNC_CONFLICT',error:error.message,failureKind:'conflict'}};
 if(error.kind==='locked') return {status:403,body:{code:'SYNC_LOCKED',error:error.message,failureKind:'locked',desktopRequired:true}};
 return null;
}

